import{_ as s,c as e,o as a,V as l}from"./chunks/framework.e2d10ea7.js";const g=JSON.parse('{"title":"依赖包的版本更新，但是安装时找不到的解决方案","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge-module/node/develop-version.md","filePath":"knowledge-module/node/develop-version.md"}'),n={name:"knowledge-module/node/develop-version.md"},p=l('<h1 id="依赖包的版本更新-但是安装时找不到的解决方案" tabindex="-1">依赖包的版本更新，但是安装时找不到的解决方案 <a class="header-anchor" href="#依赖包的版本更新-但是安装时找不到的解决方案" aria-label="Permalink to &quot;依赖包的版本更新，但是安装时找不到的解决方案&quot;">​</a></h1><h2 id="背景-私有源" tabindex="-1">背景 （私有源） <a class="header-anchor" href="#背景-私有源" aria-label="Permalink to &quot;背景 （私有源）&quot;">​</a></h2><ul><li><p>当安装依赖的时候发现之前安装的依赖， 突然发现找不到</p></li><li><p>对比当前找不到的版本与私有源里的版本是否对的上</p></li><li><p>到npm官网上去看，是否是更新了最新版本（新发版的版本，有时下载不下来）</p></li></ul><h2 id="解决" tabindex="-1">解决 <a class="header-anchor" href="#解决" aria-label="Permalink to &quot;解决&quot;">​</a></h2><ul><li><p>当发现版本对不上， 私有源里下不下来，而且切换npm源 也下不下来时</p></li><li><p>可以直接下载npm中对应版本的.tgz压缩包</p></li><li><p>再将下载后的压缩包手动上传到私有源即可 （原则上私有源在找不到对应版本时， 会自动到npm上下载到自己本地）</p></li><li><p>下载 .tgz 的包的指令 （创建一个目录， 在目录中执行命令，下载的文件就在目录里面）</p></li></ul><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">curl </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;">O </span><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmjs.org/&lt;package-name&gt;/-/&lt;package-name&gt;-&lt;version&gt;.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>下载案例：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">curl </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;">O </span><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmjs.org/lodash-es/-/lodash-es-4.17.21.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>需要注意：当我们需要安装摸个组下面的摸个依赖包， 例如下面的依赖， 在下载的时候， 需要在后面指定版本的时候移除组的名称</li></ul><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">curl </span><span style="color:#89DDFF;">-</span><span style="color:#A6ACCD;">O </span><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmjs.org/@babel/helper-plugin-utils/-/helper-plugin-utils-7.25.9.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="另外一种下载方式-直接访问连接下载" tabindex="-1">另外一种下载方式 直接访问连接下载 <a class="header-anchor" href="#另外一种下载方式-直接访问连接下载" aria-label="Permalink to &quot;另外一种下载方式 直接访问连接下载&quot;">​</a></h3><ul><li>npm 源</li></ul><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmjs.org/@babel/helper-plugin-utils/-/helper-plugin-utils-7.25.9.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>淘宝源</li></ul><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmmirror.com/@babel/helper-create-class-features-plugin/-/@babel/helper-create-class-features-plugin-7.27.0.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">https</span><span style="color:#89DDFF;">:</span><span style="color:#676E95;font-style:italic;">//registry.npmmirror.com/@babel/helper-create-class-features-plugin/-/helper-create-class-features-plugin-7.27.0.tgz</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',16),t=[p];function r(i,o,c,d,u,m){return a(),e("div",null,t)}const b=s(n,[["render",r]]);export{g as __pageData,b as default};
